import re
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(ip_address):
    """
    Extract and validate a public IPv4 address from a JSON response string.

    Args:
        ip_address (str): JSON response containing an IP address somewhere inside.

    Returns:
        str: The valid public IP address, or 'Invalid IP address received'.
    """
    try:
        data = json.loads(ip_address)
    except (TypeError, json.JSONDecodeError):
        return 'Invalid IP address received'

    # Collect candidate strings that may contain an IP
    candidates = []

    def collect_strings(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_strings(v)
        elif isinstance(obj, list):
            for v in obj:
                collect_strings(v)
        elif isinstance(obj, str):
            candidates.append(obj)

    collect_strings(data)

    # Try to find and validate the first matching IP
    for s in candidates:
        match = re.search(IP_REGEX, s)
        if not match:
            continue
        ip = match.group(0)
        # Validate IPv4 numerically and format-wise
        parts = ip.split('.')
        if len(parts) != 4:
            continue
        valid = True
        for part in parts:
            # Prevent leading +/-, empty, non-digit
            if not part.isdigit():
                valid = False
                break
            n = int(part)
            if n < 0 or n > 255:
                valid = False
                break
        if valid:
            return ip

    return 'Invalid IP address received'
