import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    """
    Extract all URLs from a string-serialized JSON dict using a specific URL pattern
    and return a dict with URLs as keys and their occurrence counts as values.

    Args:
        json_str (str): A string containing a JSON-serialized dict.
        top_n (int): Optional; if > 0, return only the top_n most common URLs.
                     If <= 0, return counts for all URLs.

    Returns:
        dict: {url: count, ...}
    """

    # Try to parse JSON; if it fails, treat input as plain string
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        data = json_str

    # Flatten all string content from the JSON structure into one list of strings
    def extract_strings(obj):
        if isinstance(obj, str):
            return [obj]
        elif isinstance(obj, dict):
            res = []
            for v in obj.values():
                res.extend(extract_strings(v))
            return res
        elif isinstance(obj, list):
            res = []
            for v in obj:
                res.extend(extract_strings(v))
            return res
        else:
            return []

    all_strings = extract_strings(data)

    # Specific URL pattern:
    # - schemes: http or https
    # - domain: letters/digits/dots/hyphens
    # - optional path/query/fragment
    url_pattern = re.compile(
        r'https?://'                  # scheme
        r'[A-Za-z0-9.-]+'             # domain
        r'(?:/[^\s"\'<>]*)?'          # optional path, avoiding whitespace and obvious delimiters
    )

    urls = []
    for s in all_strings:
        urls.extend(url_pattern.findall(s))

    counts = Counter(urls)

    if top_n > 0:
        # Keep only top_n most common
        return dict(counts.most_common(top_n))
    else:
        # Return all
        return dict(counts)

