import collections
import json
import os

def task_func(directory_path: str) -> dict:
    """
    Count total appearances of all keys in all JSON files in the specified directory.

    Args:
        directory_path (str): Path to the directory containing JSON files.

    Returns:
        dict: A dictionary with keys from JSON files as keys and their counts as values.
    """
    def count_keys(obj, counter):
        """Recursively count keys in a JSON-like structure."""
        if isinstance(obj, dict):
            for k, v in obj.items():
                counter[k] += 1
                count_keys(v, counter)
        elif isinstance(obj, list):
            for item in obj:
                count_keys(item, counter)

    key_counter = collections.Counter()

    # Iterate through files in the given directory
    for filename in os.listdir(directory_path):
        if not filename.lower().endswith(".json"):
            continue  # skip non-JSON files

        file_path = os.path.join(directory_path, filename)

        # Skip if it's not a file (e.g., directory, symlink)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            count_keys(data, key_counter)
        except (json.JSONDecodeError, OSError):
            # Ignore files that cannot be read or parsed
            continue

    return dict(key_counter)
