from collections import defaultdict

def task_func(input_file="data.json"):
    # Read list of dictionaries from JSON file
    with open(input_file, "r") as f:
        data = json.load(f)

    # Collect numeric values for each key
    values_by_key = defaultdict(list)
    for item in data:
        if not isinstance(item, dict):
            continue
        for key, value in item.items():
            # Keep only int/float, ignore bool (since bool is subclass of int)
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_by_key[key].append(value)

    # Compute mean and median for each key
    stats = {}
    for key, vals in values_by_key.items():
        if len(vals) == 0:
            continue
        arr = np.array(vals, dtype=float)
        stats[key] = {
            "mean": float(np.mean(arr)),
            "median": float(np.median(arr)),
        }

    # Create DataFrame, indexed and sorted by variable names (keys)
    df = pd.DataFrame.from_dict(stats, orient="index")
    df.index.name = "variable"
    df = df.sort_index()

    return df

