import numpy as np
from collections import defaultdict
import json
import csv

# Constants
def task_func(input_file, output_file):
    # Read JSON file (expects a list of dictionaries)
    with open(input_file, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Collect numeric values for each key
    values_by_key = defaultdict(list)
    for item in data:
        if not isinstance(item, dict):
            continue
        for k, v in item.items():
            # Consider only numeric values
            if isinstance(v, (int, float)):
                values_by_key[k].append(v)

    # Compute mean and median for each key
    stats = {}
    for k, vals in values_by_key.items():
        if not vals:
            continue
        arr = np.array(vals, dtype=float)
        stats[k] = {
            'mean': float(np.mean(arr)),
            'median': float(np.median(arr))
        }

    # Write results to CSV
    # CSV columns: field, mean, median
    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['field', 'mean', 'median'])
        for field, mm in stats.items():
            writer.writerow([field, mm['mean'], mm['median']])

    return stats
